package edu.smartstudy.tutor;
import com.fasterxml.jackson.core.type.TypeReference;import com.fasterxml.jackson.databind.ObjectMapper;import edu.smartstudy.material.*;import edu.smartstudy.user.UserRepository;import jakarta.validation.Valid;import jakarta.validation.constraints.*;import java.util.*;
import org.springframework.beans.factory.annotation.Value;import org.springframework.http.*;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;import org.springframework.web.client.RestClient;
@RestController @RequestMapping("/api/v1/tutor")public class TutorController{private final TutorConversationRepository conversations;private final TutorMessageRepository messages;private final MaterialRepository materials;private final UserRepository users;private final RestClient ml;private final ObjectMapper json;public TutorController(TutorConversationRepository conversations,TutorMessageRepository messages,MaterialRepository materials,UserRepository users,@Value("${app.ml-url}")String mlUrl,ObjectMapper json){this.conversations=conversations;this.messages=messages;this.materials=materials;this.users=users;ml=RestClient.builder().baseUrl(mlUrl).build();this.json=json;}private Long owner(Authentication a){return users.findByEmailIgnoreCase(a.getName()).orElseThrow().getId();}public record AskRequest(@NotBlank @Size(max=1000)String question,@jakarta.validation.constraints.NotNull @Positive Long materialId,@Positive Long conversationId){}@GetMapping("/conversations")public List<TutorConversation> list(Authentication a){return conversations.findTop50ByOwnerIdOrderByCreatedAtDesc(owner(a));}@GetMapping("/conversations/{id}")public ResponseEntity<?> detail(@PathVariable Long id,Authentication a){Long user=owner(a);return conversations.findByIdAndOwnerId(id,user).<ResponseEntity<?>>map(c->ResponseEntity.ok(Map.of("conversation",c,"messages",messages.findByConversationIdOrderByCreatedAtAsc(id).stream().map(this::messageView).toList()))).orElseGet(()->ResponseEntity.notFound().build());}private Map<String,Object> messageView(TutorMessage m){try{return Map.of("id",m.getId(),"role",m.getRole(),"content",m.getContent(),"sources",m.getSourcesJson()==null?List.of():json.readValue(m.getSourcesJson(),new TypeReference<List<Map<String,Object>>>(){}),"createdAt",m.getCreatedAt());}catch(Exception e){throw new IllegalStateException(e);}}@PostMapping("/ask")public ResponseEntity<?> ask(@RequestBody @Valid AskRequest input,Authentication a)throws Exception{Long student=owner(a);Material material=materials.findByIdAndOwnerId(input.materialId(),student).orElse(null);if(material==null)return ResponseEntity.notFound().build();if(!"COMPLETED".equals(material.getStatus())||material.getExtractedText()==null)return ResponseEntity.status(409).body(Map.of("error","Choose a processed material first."));TutorConversation conversation;if(input.conversationId()==null)conversation=conversations.save(new TutorConversation(student,input.question().trim().substring(0,Math.min(120,input.question().trim().length()))));else{conversation=conversations.findByIdAndOwnerId(input.conversationId(),student).orElse(null);if(conversation==null)return ResponseEntity.notFound().build();}messages.save(new TutorMessage(conversation.getId(),"USER",input.question().trim(),null));Map<?,?> found;try{found=ml.post().uri("/ml/v1/semantic-search").contentType(MediaType.APPLICATION_JSON).body(Map.of("question",input.question(),"context",material.getExtractedText())).retrieve().body(Map.class);}catch(Exception e){return ResponseEntity.status(503).body(Map.of("error","The study-material search service is temporarily unavailable."));}List<Map<String,Object>> hits=json.convertValue(found.get("matches"),new TypeReference<>(){});if(hits==null)hits=List.of();List<Map<String,Object>> sources=new ArrayList<>();StringBuilder answer=new StringBuilder();if(hits.isEmpty())answer.append("I couldn't find support for that question in the selected study material. Try another question or check a different note.");else{answer.append("Here are the closest passages in ").append(material.getTitle()).append(". Use them to form an answer and verify the full context in your source:");for(var hit:hits){Map<String,Object> source=Map.of("materialTitle",material.getTitle(),"reference",Objects.toString(hit.get("source_reference"),"document"),"text",Objects.toString(hit.get("text"),""));sources.add(source);answer.append("\n\n? ").append(source.get("text")).append(" (").append(source.get("reference")).append(")");}}messages.save(new TutorMessage(conversation.getId(),"TUTOR",answer.toString(),json.writeValueAsString(sources)));return ResponseEntity.ok(Map.of("conversationId",conversation.getId(),"messages",messages.findByConversationIdOrderByCreatedAtAsc(conversation.getId()).stream().map(this::messageView).toList(),"notice","This baseline retrieves matching excerpts; it does not generate a new explanation. Check the cited source passage."));}}
